\begin{gathered}
\begin{aligned}
R_x &= E\left[x(t)x^H(t)\right] \\
&= E\left[\{As(t) + n(t)\}\{As(t) + n(t)\}^H\right] \\
&= E\left[As(t)s^H(t)A^H\right] + E\left[n(t)n^H(t)\right] + E\left[As(t)n^H(t)\right] + E\left[n(t)s^H(t)A^H\right] \\
&= AR_sA^H + \sigma^2 I
\end{aligned}
\\[3ex]
R_s = E\left[s(t)s^H(t)\right], \qquad E\left[s(t)n^H(t)\right] = 0
\end{gathered}
